-- Outreach v10 (owner, 2026-11-05): scale law-firm outreach nationally, for
-- every service (after-hours intake line, website chat assistant, website
-- design, AI use policy). Includes everything from v8 (medical offices with a
-- checked website problem), so running this one file is enough.
--   outreach: first emails to law firms + medical offices, 15 a day (law
--     firms first); new law-firm note + follow-ups.
--   places_queries: search ONLY law firms and medical offices (no search
--     budget spent on categories we don't email); law-firm searches also run
--     in 42 large US metros. The 950-searches-a-month free-tier guard stays.
-- Undo: set first_email_categories / only_categories to null.

update settings set value = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(value,
    '{touch_sets,legal}', $j$[{"step": 1, "delay_days": 0, "subject": "After-hours calls at {business_name}", "body": "Hi,\n\nWhen someone needs a lawyer at 8 p.m., they often hire whichever firm picks up. We help small firms like {business_name} catch those clients, and use AI without the ethics headaches:\n\n- an after-hours intake line that answers every call, says it's an AI, takes the caller's details and matter type, and emails you a summary by morning (it never gives legal advice)\n- a chat assistant on your website that answers common questions and books consultations\n- a new or refreshed website built to show up when people search for a lawyer near them\n- a plain-English AI use policy for your team, in line with ABA Formal Opinion 512{site_line}\n\nFixed prices, and the first conversation is free. I'm Deven, and I run Wade Capital.\n\n{booking_line}\n\n{sender_name}"}]$j$::jsonb, true),
    '{followup_sets,legal}', $j$[{"step": 2, "delay_days": 4, "subject": "After-hours calls at {business_name}", "body": "Hi, a quick follow-up. Here's the intake line in practice: someone calls {business_name} at 9 p.m., hears they've reached the firm's AI assistant, gives their name, number and what happened, and you have a summary in your inbox before morning. If a call is too much right now, reply \"send it\" and I'll email a one-page AI use policy starter for small firms, free.\n\n{sender_name}"}, {"step": 3, "delay_days": 10, "subject": "After-hours calls at {business_name}", "body": "Hi, I'll close the file after this one. If after-hours intake, a website chat assistant, a new site or an AI policy becomes a priority for {business_name}, reply \"yes\" and I'll send a few times.\n\n{sender_name}"}]$j$::jsonb, true),
    '{touch_sets,medical}', $j$[{"step": 1, "delay_days": 0, "subject": "{business_name}'s website on a phone", "body": "Hi,\n\nI was looking up {business_name} on my phone and noticed your website {issue_line}. For a practice, that's usually the moment a new patient gives up and calls the next office on Google.{sample_line}\n\nI'm Deven, and I run a small studio, Wade Capital, that fixes exactly this for local practices at a fixed price. We also help practices put AI to work safely: a plain-English policy for how staff use tools like ChatGPT without putting patient information at risk, and the tools set up the right way.\n\n{booking_line}\n\n{sender_name}"}]$j$::jsonb, true),
    '{followup_sets,medical}', $j$[{"step": 2, "delay_days": 4, "subject": "{business_name}'s website on a phone", "body": "Hi, a quick follow-up. If a call is too much right now, just reply \"send it\" and I'll email you the three fixes I'd make first on {business_name}'s site, free, no call needed.\n\n{sender_name}"}, {"step": 3, "delay_days": 10, "subject": "{business_name}'s website on a phone", "body": "Hi, I'll close the file after this one. If the website or an AI policy for your staff becomes a priority for {business_name}, reply \"yes\" and I'll send a few times.\n\n{sender_name}"}]$j$::jsonb, true),
    '{problem_required_categories}', '["medical"]'::jsonb, true),
    '{first_email_categories}', '["legal", "medical"]'::jsonb, true),
    '{max_new_sends_per_run}', '15'::jsonb, true)
where key = 'outreach';

