-- Mark every law-firm search term as national.
update settings set value = jsonb_set(value, '{categories}', (
    select jsonb_agg(case when c->>'category' = 'legal' then c || '{"national": true}'::jsonb else c end)
    from jsonb_array_elements(value->'categories') c))
where key = 'places_queries';
